INSERT INTO `questions` VALUES (1,1,1,9,'Romeo & Juliet Act 3',23,'What does Capulet tell his wife to say to Juliet? testing edit functionality','multiple_choice','That she will marry Paris on Thursday','That she must leave Verona immediately','That Romeo has been banished','That Tybalts funeral will be held tomorrow','That Romeo has been banished','medium','2026-02-24 04:04:21'),(2,1,1,9,'Romeo & Juliet Act 3',23,'As Romeo is preparing to leave Juliet, what argument does she use to convince him to stay?','short_answer',NULL,NULL,NULL,NULL,'She argues that it is the nightingale singing, not the lark, meaning it is still night.','medium','2026-02-24 04:04:21'),(3,1,1,9,'Romeo & Juliet Act 3',23,'Tybalt and Mercutio fight because Mercutio seeks to protect Romeos honour.','true_false','True','False',NULL,NULL,'True','easy','2026-02-24 04:04:21'),(4,1,1,9,'Romeo & Juliet Act 3',23,'When Lady Capulet threatens to send someone to Mantua to poison Romeo, what does Juliet say?','multiple_choice','She begs her mother not to','She says she will be the one to mix the poison','She threatens to run away','She says nothing and leaves the room','She says she will be the one to mix the poison','medium','2026-02-24 04:04:21'),(5,1,1,9,'Romeo & Juliet Act 3',23,'In Act 3 Scene 4, Capulet informs Paris of what?','multiple_choice','Juliets agreement to marry him','Romeos banishment from Verona','Tybalts funeral arrangements','His plan to disown Juliet','Juliets agreement to marry him','easy','2026-02-24 04:04:21'),(6,1,1,10,NULL,15,'What is the primary purpose of Act 1 in Romeo and Juliet?','multiple_choice','To introduce the feud and main characters','To resolve the central conflict','To present the wedding scene','To show the final battle','To introduce the feud and main characters','easy','2026-03-19 21:35:20'),(7,1,1,10,NULL,16,'How does Act 2 develop the relationship between Romeo and Juliet?','short_answer',NULL,NULL,NULL,NULL,NULL,'medium','2026-03-19 21:35:20'),(8,1,1,10,NULL,1